import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"StoryMem: Multi-shot Long Video Storytelling with Memory","description":"","frontmatter":{"title":"StoryMem: Multi-shot Long Video Storytelling with Memory","arxiv":"2512.19539","date":"2025-12-22","authors":"Kaiwen Zhang, Liming Jiang, Angtian Wang, Jacob Zhiyuan Fang, Tiancheng Zhi, Qing Yan, Hao Kang, Xin Lu, Xingang Pan","categories":"cs.CV","topics":"智能体视频生成, 长视频记忆, 多镜头一致性","outline":[2,2]},"headers":[],"relativePath":"papers/2512.19539.md","filePath":"papers/2512.19539.md","lastUpdated":null}'),e={name:"papers/2512.19539.md"};function l(r,s,m,i,c,o){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="storymem-multi-shot-long-video-storytelling-with-memory" tabindex="-1">StoryMem: Multi-shot Long Video Storytelling with Memory <a class="header-anchor" href="#storymem-multi-shot-long-video-storytelling-with-memory" aria-label="Permalink to &quot;StoryMem: Multi-shot Long Video Storytelling with Memory&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2512.19539" target="_blank" rel="noreferrer">2512.19539</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-12-22</td></tr><tr><td><strong>作者</strong></td><td>Kaiwen Zhang, Liming Jiang, Angtian Wang, Jacob Zhiyuan Fang, Tiancheng Zhi, Qing Yan, Hao Kang, Xin Lu, Xingang Pan（NTU S-Lab、ByteDance）</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>把此前镜头筛出的关键帧当作&quot;记忆帧&quot;塞进 I2V 模型的条件 latent，用负的 RoPE 时间偏移把它们放在时间轴负半轴上，让多镜头故事的一致性变成一次普通的图生视频条件化。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/agentic">智能体视频生成</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">取全文的记录</p><p>该 arXiv 条目的 abs 页只提供 PDF 与 TeX 源码，未挂 HTML 入口，ar5iv 返回 <code>Conversion to HTML had a Fatal error</code>。手动拼接 <code>https://arxiv.org/html/2512.19539v1</code> 可以打开完整正文，本页依据该版本撰写。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>多镜头故事视频的一致性问题有一个很具体的形状：第 7 个镜头里的主角要和第 1 个镜头里的是同一个人，穿同一件衣服，站在同一栋房子前面。逐镜头调用 I2V 模型的做法只能把<strong>上一镜头的末帧</strong>当条件，于是信息以链式方式传递，误差逐镜头累积；等到第 7 个镜头，最初的外观已经漂得看不出来了。</p><p>另一条路是端到端整段生成，把所有镜头放进同一次去噪。它的一致性更好，但序列长度带来的算力成本限制了镜头数量与时长，而且每加一个镜头就要重新生成整段，不能增量续写。</p><p>StoryMem 选择的位置介于两者之间：保持逐镜头生成的增量性，但让每个镜头能够读到<strong>任意历史镜头</strong>的关键帧，而不只是紧邻的上一帧。这样一致性的传递路径从&quot;链&quot;变成&quot;星&quot;，第 7 个镜头可以直接看第 1 个镜头，误差不再逐跳累积。这件事的价值在于它不需要改动基座架构，只需要改条件的组织方式。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>首尾帧续接</strong>（用上一镜头末帧作为下一镜头首帧条件）是最朴素的方案，问题就是上面说的链式漂移；而且末帧未必包含主体，镜头结束时人可能已经走出画面。</p><p><strong>训练无关的注意力共享</strong>（StoryDiffusion 一类，配合 Wan2.2-I2V 使用）通过在生成时让不同镜头共享 attention 来维持一致性，不需要训练。表 1 里它的跨镜头一致性是 0.4600，在所有对照中最高，说明这条路确实有效；但它对镜头数增长的扩展性受制于共享注意力的开销，且共享是全局无选择的，无法指定&quot;记住这个人，忘掉那个背景&quot;。</p><p><strong>上下文 LoRA</strong>（IC-LoRA 配 Wan2.2-I2V）用少量参数把多张参考图组织进上下文，表 1 中跨镜头一致性 0.4110，是三个对照里最低的。</p><p><strong>端到端整体生成</strong>（HoloCine）在表 1 中跨镜头一致性 0.4628、Top-10 一致性 0.5005，是最强的对照。它的短板在增量性：整段一次生成，续写要重来。</p><p>四条路线都没有解决同一件事：<strong>该记住哪些帧</strong>。前人要么全记（整段生成、注意力共享），要么只记最近一帧（首尾帧续接），没有一个显式的选择与淘汰机制。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>从一个观察开始：I2V 模型本身就是&quot;给定图像，生成后续视频&quot;，它已经具备把一张图的外观搬进视频的能力。那么让第 7 个镜头保持一致的最省事办法，是把第 1 个镜头里的那张关键帧也当成条件图像喂给它。问题是 I2V 的条件接口只有一个位置——首帧。</p><p>要放进多张，就得回答&quot;这些帧在时间轴的哪里&quot;。把它们排在正时间轴上会与要生成的帧冲突，模型会以为要生成的是它们的后续。放在负半轴是自然的选择：用负的 RoPE 偏移把记忆帧标记为&quot;发生在这段之前的事&quot;，模型就能把它们理解为上下文而非需要延续的运动。</p><p>接下来是选帧。每个历史镜头都塞进来会让条件无限增长，所以需要两级筛选：语义上要与当前镜头相关（否则是噪声），画质上要过得去（模糊或构图差的帧会把坏外观传下去）。再加一个不被淘汰的&quot;记忆锚&quot;，保证最初设定的角色外观永远在场，滑窗淘汰其余的。这三件事合起来就是完整的记忆管理策略。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>跨镜头一致性可以完全化归为&quot;给 I2V 模型多喂几张正确的条件图&quot;。关键在于用负的时间位置索引告诉模型这些帧属于过去、不需要被延续，以及用语义与美学两道筛子决定哪几张值得留下。记忆是视觉的，选择才是方法。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p><strong>基座与参数</strong>：Wan2.2-I2V-A14B，在所有 DiT 线性层上加 rank-128 LoRA，约新增 0.7B 激活参数。基座本身不动。</p><p><strong>Memory-to-Video 条件化</strong>：记忆帧先过 3D VAE 编码，与代表待生成部分的零填充帧沿时间维拼接，构成条件 latent；同时给出一个二值 mask 标明哪些位置是记忆、哪些是要生成的。时间位置索引取</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord">−</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">m</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">−</span><span class="mord">2</span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">−</span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1</span><span class="mclose">}</span><span class="mpunct">,</span></span></span></span></span></p><p>其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">m</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是记忆帧数、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span></span></span></span> 是待生成帧数、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span></span></span></span> 是负偏移步长。记忆帧因此落在时间轴负半轴且彼此间隔 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span></span></span></span>，与从 0 开始的待生成帧完全分开。</p><p><strong>训练</strong>：40 万条 5 秒单镜头视频，每条配 1 到 5 条语义相关的视频作为记忆来源；训练时记忆长度在 1 到 10 帧之间随机采样，负偏移 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">5</span></span></span></span>。随机化记忆长度是为了让推理时能用任意数量的记忆帧。</p><p><strong>推理时的记忆管理</strong>：每个镜头最多贡献 3 个关键帧；关键帧用 CLIP 特征配动态阈值挑选，初始语义相似度阈值 0.9；美学过滤用 HPSv3，阈值 3.0；前 3 帧设为 memory sink 永不淘汰，其余按滑窗淘汰，两者结合避免记忆无限增长。</p><p><strong>一个具体例子</strong>：故事有 10 个镜头。生成第 8 个镜头时，系统从前 7 个镜头已产出的帧里按 CLIP 相似度找出与第 8 条 prompt 语义相关的候选，用 HPSv3 剔掉画质不达标的，取不超过 3 帧，再拼上 3 帧 memory sink（通常来自第 1 个镜头，携带最初的角色设定），一共约 6 帧记忆，编码后按上式的负时间索引与零填充帧拼接，送进带 LoRA 的 Wan2.2-I2V 去噪。</p><p><strong>ST-Bench</strong>：用 GPT-5 生成 30 个故事脚本，每个含 8 到 12 条镜头 prompt，共 300 条镜头级 prompt。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>方法的形式化集中在时间位置索引的构造上。设待生成片段有 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span></span></span></span> 帧，索引为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span>；记忆帧有 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">m</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 帧，索引为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord">−</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">m</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">−</span><span class="mord">2</span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">−</span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span></span></span></span>。RoPE 把位置编码成旋转角，因此两个 token 之间的相对位置决定它们的 attention 偏置。记忆帧与待生成首帧的最小距离是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span></span></span></span>，与最后一帧的距离是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span>。</p><p>取 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">5</span></span></span></span> 而非 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span> 的作用可以这样理解：若记忆帧紧贴在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mord">−</span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">−</span><span class="mord">2</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span></span></span></span> 上，它们在相对位置上与&quot;上一帧&quot;没有区别，模型会把它们当作需要延续的运动前缀，于是产生插值式的运动衔接。拉开间隔 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span></span></span></span> 之后，记忆帧在相对位置上表现为一组稀疏的、彼此不连续的时刻，模型更容易把它们读作离散的外观参考。这一解释是我基于 RoPE 相对位置性质做的推断，论文给出的是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">5</span></span></span></span> 这个取值本身。</p><p>条件 latent 的构造可以写成沿时间维的拼接加掩码：把记忆帧的 VAE latent 与零填充部分拼起来得到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">c</span></span></span></span>，二值 mask <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">m</span></span></span></span> 在记忆位置为 1、生成位置为 0，去噪网络接收 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">c</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">m</span><span class="mclose">)</span></span></span></span>。mask 的存在使得同一套权重可以处理任意记忆帧数，训练时对 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">m</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 做 1 到 10 的随机采样正是为了让这个接口在推理时可变长。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p>ST-Bench 上的表 1 按五列组织：美学、全局 prompt following、单镜头 prompt following、跨镜头一致性、Top-10 一致性。</p><table tabindex="0"><thead><tr><th>方法</th><th>美学</th><th>PF(global)</th><th>PF(shot)</th><th>跨镜头一致性</th><th>Top-10 一致性</th></tr></thead><tbody><tr><td>StoryDiffusion + Wan2.2-I2V</td><td>0.6085</td><td>0.2288</td><td>0.2349</td><td>0.4600</td><td>0.4732</td></tr><tr><td>IC-LoRA + Wan2.2-I2V</td><td>0.5704</td><td>0.2131</td><td>0.2181</td><td>0.4110</td><td>0.4296</td></tr><tr><td>HoloCine</td><td>0.5653</td><td>0.2199</td><td>0.2125</td><td>0.4628</td><td>0.5005</td></tr><tr><td>StoryMem</td><td>0.6133</td><td>0.2289</td><td>0.2313</td><td>0.5065</td><td>0.5337</td></tr></tbody></table><p>核心问题是记忆机制能不能提升跨镜头一致性。答案是能：0.5065 相对 HoloCine 的 0.4628 高 9.4%（这条比例我按表中数值验算与正文一致），论文另称相对基座高 28.7%。美学与全局 prompt following 也同时最高，说明一致性不是靠牺牲画质换来的。</p><p>一个不能略过的细节是单镜头 prompt following：StoryMem 的 0.2313 低于 StoryDiffusion 的 0.2349。记忆帧作为条件在提升一致性的同时会把画面往历史外观上拉，与当前镜头 prompt 的新要求存在张力。这是方法内在的权衡，不是噪声。</p><p>消融（表 2，第 4 列即跨镜头一致性）：去掉语义选择 0.4878，去掉美学过滤 0.4844，去掉 memory sink 0.4891，完整方法 0.5065。三个组件各自贡献约 0.017 到 0.022，量级接近，说明记忆管理的三道机制没有哪一个是主导，收益来自它们的叠加。反过来说，任意单个组件的消融幅度都不大，这类差距在 300 条 prompt 的规模上应当配上方差报告才更可信。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句版</strong>：跨镜头一致性可以化归为 I2V 的多图条件化问题，不需要新架构。负 RoPE 偏移把记忆帧放到时间轴负半轴，是让模型区分&quot;上下文&quot;与&quot;待延续前缀&quot;的关键接口。训练时随机化记忆长度换来推理时的可变长记忆，这是让方法实用的工程点。语义选择、美学过滤、memory sink 三者贡献量级相当，记忆管理是一整套而不是单点技巧。记忆越强，单镜头 prompt following 越受压制，0.2313 对 0.2349 就是这个权衡的价格。</p><p><strong>3 句版</strong>：在 Wan2.2-I2V 上加 rank-128 LoRA，把历史关键帧编码后以负时间索引拼进条件 latent，实现跨镜头记忆。跨镜头一致性 0.5065，比 HoloCine 高 9.4%，美学与全局 prompt following 同时最高。代价是单镜头 prompt following 略降，且记忆是纯视觉的、不含文本元信息。</p><p><strong>1 句版</strong>：用负时间位置把历史关键帧当条件塞进 I2V，多镜头一致性就变成了一个选帧问题。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条是：<strong>纯视觉的记忆足以标识&quot;是谁&quot;</strong>。记忆条目只有像素，没有任何文本元信息说明这一帧里的人是主角 A 还是配角 B。作者自己在 limitation 里点明了这个设计约束及其原因：Wan2.2 是 cross-attention 结构的 DiT 而非 MMDiT，文本与视觉 token 不在同一序列里，因此没有现成的位置把&quot;这是 Anna&quot;这样的标签与记忆帧绑定。</p><p>后果是可预测的：多角色场景下检索会出错。当第 8 个镜头的 prompt 说&quot;Anna 走进房间&quot;，系统靠 CLIP 相似度去历史帧里找，而 CLIP 特征对&quot;同一场景里的另一个人&quot;和&quot;目标人物&quot;的区分度有限，很容易把配角的帧选进记忆，于是生成出的人是错的。作者明确承认了这一点，这是这篇论文最诚实的地方，也是它最直接的失效边界。</p><p>这个假设失效的代价是整个贡献塌掉：如果检索的是错误的实体，记忆机制不但不提升一致性，反而会主动把错误外观注入后续镜头，比不用记忆更糟。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不必训练 40 万条数据，用小规模验证接口设计即可：</p><ol><li>取任意 I2V 基座，加 rank 较小的 LoRA，用 5k 条短视频做训练，每条随机取 1 到 10 帧作为记忆（记忆帧从同一视频的随机时刻取，模拟&quot;语义相关&quot;）。</li><li>训两个变体：记忆帧时间索引为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mord">−</span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">−</span><span class="mord">2</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span></span></span></span>（紧贴）与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord">−</span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">−</span><span class="mord">2</span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span></span></span></span>（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">5</span></span></span></span>，拉开）。</li><li>生成 5 镜头故事，测跨镜头一致性与镜头首帧的运动量（光流幅度）。</li><li>判据：若紧贴变体的运动量显著偏低、画面呈现插值式衔接，则负偏移步长 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span></span></span></span> 的作用得到验证；若两者无差别，则 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">5</span></span></span></span> 只是超参而非机制，§6 里我给出的那条推断应当被推翻。</li></ol><p>这个实验只测接口，不测选帧策略，一周内可完成。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>针对方法的退化解设计攻击。记忆帧是以 VAE latent 形式直接拼进条件的，模型完全可以通过<strong>近似复制记忆帧</strong>来最大化跨镜头一致性。构造这样一个平凡基线：把 memory sink 的第 1 帧直接复制成整个镜头的所有帧（即一段静止视频），提交评测。它的跨镜头一致性按构造应当接近上界，远超 0.5065，而它的运动量为零、单镜头 prompt following 极差。</p><p>这个基线一旦跑出高分，就说明表 1 的第 4、5 列必须与运动量、单镜头 prompt following 联合解读，不能单独作为方法优劣的判据。而 StoryMem 的单镜头 prompt following 恰好是它相对 StoryDiffusion 唯一落后的一列（0.2313 对 0.2349），这个方向与&quot;记忆条件把画面往历史外观拉&quot;的预测一致。因此一个更有力的质疑是：0.5065 里有多少来自真正的实体理解，有多少来自条件帧的外观拷贝？</p><p>可执行的区分方案：构造一批 prompt，要求同一角色在后续镜头<strong>改变外观的非身份属性</strong>（换衣服、换发型、从室内走到雨里），再测一致性指标。如果指标随着这类合理变化而下降，说明它奖励的是像素不变而非身份不变。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p>驱动 idea 的局限就是 §9：记忆没有名字。当前记忆是一个视觉帧的集合，检索靠 CLIP 相似度，本质是外观最近邻，无法表达&quot;这是 Anna，不是那个穿类似衣服的路人&quot;。</p><p>可借鉴的相邻工具来自实体链指与共指消解：把记忆条目升级为 (实体 ID, 视觉证据集合) 的二元组，实体 ID 由脚本侧的文本提供并在整个故事内唯一，视觉证据由检测与跟踪自动挂载。检索从&quot;找最像的帧&quot;变成&quot;取指定实体的证据&quot;，多角色歧义在原理上消失。这里的关键难点是条件接口：cross-attention DiT 没有地方注入实体标签，因此需要把实体 ID 编码进记忆帧的位置或通道，让不同实体的记忆占据可区分的坐标——这本身是一个值得单独做的表示问题。</p><p>第一个实验：构造 100 条双角色故事（两个角色外观相近，例如同性别同发色），对比三种检索——CLIP 最近邻、带实体 ID 的定向检索、oracle（人工指定正确帧）。测量后续镜头中主角身份正确的比例。若 CLIP 最近邻与 oracle 的差距很大而定向检索能补上大半，就证明&quot;记忆需要名字&quot;这一判断，并直接给出一条比继续调阈值更有前景的改进方向。</p>',59)])])}const d=a(e,[["render",l]]);export{g as __pageData,d as default};
